    '%s سطر فيهم صورة. النص هيبقى عن اللي في الصورة فعلًا، بس أغلى بكتير وأبطأ (5 صور في كل طلب). الموديل لازم يكون بيقرا صور.' => '%s سطر تحتوي على صورة. سيُكتب النص وفق محتوى الصورة فعلًا، لكنه أعلى تكلفة وأبطأ بكثير (5 صور في كل طلب). يجب أن يدعم النموذج قراءة الصور.',
    'هنكتب نص لـ %s سطر نصهم فاضي، من وصف الصورة أو اسمها. بيستهلك من رصيد الذكاء الاصطناعي.' => 'سنكتب نصًا لـ %s سطر نصها فارغ، اعتمادًا على وصف الصورة أو اسمها. يُخصم ذلك من رصيد الذكاء الاصطناعي.',
