    'التقويم بيجيب كل المنشورات المجدولة في الفترة اللي قدامك، ولما تقلّب بيجيب الباقي. اضغط على يوم فاضي في المستقبل عشان تعمل منشور فيه.' => 'يعرض التقويم كل المنشورات المجدولة في الفترة الظاهرة، ويحمّل الباقي عند التنقل. اضغط على يوم فارغ في المستقبل لإنشاء منشور فيه.',
