    'اقفل الأقسام اللي الشركة دي مش بتستخدمها، عشان القائمة تبقى أبسط للفريق. مفيش بيانات بتتمسح.' => 'أغلق الأقسام التي لا تستخدمها هذه الشركة لتبسيط القائمة للفريق. لن تُحذف أي بيانات.',
