    'تكلفة الضغطة (CPC): بتدفع كام في المتوسط عشان حد يضغط. متوسط حملاتك بعملة %s: %s. أقل = أحسن.' => 'تكلفة النقرة (CPC): متوسط ما تدفعه مقابل كل نقرة. متوسط حملاتك بعملة %s: %s. الأقل أفضل.',
    'تكلفة النتيجة: الصرف ÷ النتايج (شراء، رسالة، تفاعل حسب هدف الحملة). ده أهم رقم لو هدفك مبيعات.' => 'تكلفة النتيجة: الإنفاق ÷ النتائج (شراء أو رسالة أو تفاعل حسب هدف الحملة). وهو أهم رقم إن كان هدفك المبيعات.',
    'الأنسب للبداية: ناس عرفوك فعلًا، وغالبًا بيتحولوا أسرع.' => 'الأنسب للبداية: أشخاص يعرفونك فعلًا، وغالبًا يتحولون أسرع.',
    'عندك دافي ومشابه. الواسع بيتعمل بالاهتمامات جوه منشئ الحملات: اعمل مجموعة لكل درجة عشان تقارن.' => 'لديك جمهور دافئ ومشابه. أما الواسع فيُنشأ بالاهتمامات داخل منشئ الحملات: أنشئ مجموعة لكل درجة لتقارن بينها.',
    'ابني حملة فيها أكتر من مجموعة إعلانية، وفي كل مجموعة أكتر من إعلان. بيتحفظ لوحده، ومش بيتطلق غير بعد مراجعتك وموافقتك.' => 'أنشئ حملة تضم أكثر من مجموعة إعلانية، وفي كل مجموعة أكثر من إعلان. تُحفظ تلقائيًا، ولا تُطلق إلا بعد مراجعتك وموافقتك.',
