    'متوسط التفاعل للمنشورات اللي فيها الهاشتاج (وعدد مرات استخدامه). الأخضر أعلى من متوسطك.' => 'متوسط التفاعل للمنشورات التي تتضمن الوسم (وعدد مرات استخدامه). الأخضر أعلى من متوسطك.',
    'اربط مفتاح OpenRouter (فيه موديلات مجانية) أو Anthropic أو OpenAI أو Gemini من صفحة التكاملات.' => 'اربط مفتاح OpenRouter (يتضمن نماذج مجانية) أو Anthropic أو OpenAI أو Gemini من صفحة التكاملات.',
    'أي تعليق فيه الكلمة، حتى لو جزء من كلمة أطول.' => 'أي تعليق يحتوي الكلمة، ولو كانت جزءًا من كلمة أطول.',
    '%s كلمة · أي تعليق فيه واحدة منهم يشغلها' => '%s كلمة · يُشغّلها أي تعليق يحتوي إحداها',
    'العدد النهائي بيتحسب في الخطوة الجاية قبل الإرسال.' => 'يُحسب العدد النهائي في الخطوة التالية قبل الإرسال.',
    'هنعمل مسودة الأول ومش هيتبعت أي حاجة. في الخطوة الجاية هتشوف عدد المستلمين بالظبط وتأكد الإرسال أو تجدوله.' => 'سننشئ مسودة أولًا ولن يُرسل شيء. في الخطوة التالية سترى عدد المستلمين بدقة، ثم تؤكد الإرسال أو تجدوله.',
    'مش متحقق' => 'غير متحقق',
    'اللي الناس بتشوفه أول ما تلاقيك على جوجل' => 'ما يراه الناس أولًا عندما يجدونك على Google',
    'الأيام اللي مواعيدها مختلفة عن العادي — جوجل بيعرضها للناس بدل المواعيد العادية' => 'الأيام ذات المواعيد المختلفة عن المعتاد — يعرضها Google بدلًا من المواعيد المعتادة',
    'دوس على الخاصية عشان تفعّلها — بتظهر للناس كعلامات على ملفك' => 'اضغط الخاصية لتفعيلها — تظهر للناس كعلامات على ملفك',
    'زراير "احجز" و"اطلب" اللي بتظهر على ملفك وبتودّي لموقعك' => 'أزرار "احجز" و"اطلب" التي تظهر على ملفك وتنقل الزائر إلى موقعك',
    'لحد تاني يوم' => 'حتى اليوم التالي',
    'جوجل بيرفض الوصف اللي فيه أرقام تليفون أو روابط' => 'يرفض Google الوصف الذي يحتوي على أرقام هواتف أو روابط',
    'هتستبدل المواعيد في %s فروع تانية غير الفرع ده:' => 'ستُستبدل المواعيد في %s فروع أخرى غير هذا الفرع:',
    'فيه طلب تحقق مفتوح. لو اخترت التحقق بالبريد، استنى الكارت اللي فيه الكود (ممكن ياخد لحد 14 يوم)، ولو بالتليفون أو الإيميل هيوصلك كود. دخّل الكود من حساب Google Business Profile.' => 'يوجد طلب تحقق مفتوح. إذا اخترت التحقق بالبريد، فانتظر البطاقة التي تحمل الرمز (قد يستغرق ذلك حتى 14 يومًا)، وإذا اخترت الهاتف أو البريد الإلكتروني فسيصلك رمز. أدخل الرمز من حساب Google Business Profile.',
    'جوجل بيقول إن الفروع اللي فيها صور كتير ومتنوعة بتاخد طلبات اتجاهات وزيارات أكتر.' => 'يشير Google إلى أن الفروع التي تضم صورًا كثيرة ومتنوعة تحصل على طلبات اتجاهات وزيارات أكثر.',
    'خلص الرفع: %s نجحت · %s فشلت. الصور بتاخد وقت لحد ما تظهر على جوجل — حدّث الصفحة بعد شوية.' => 'اكتمل الرفع: نجح %s · فشل %s. قد تستغرق الصور بعض الوقت حتى تظهر على Google — حدّث الصفحة بعد قليل.',
    'اتكتبت %s مسودة. راجع كل رد ودوس "رد" عليه — مفيش حاجة اتبعتت.' => 'كُتبت %s مسودة. راجع كل رد واضغط "رد" — لم يُرسل أي شيء بعد.',
    'شكرًا يا {name} على رأيك. يهمنا نعرف إيه اللي كان ممكن يخلي تجربتك أحسن، ابعتلنا رسالة خاصة.' => 'شكرًا لك يا {name} على رأيك. يهمنا أن نعرف ما الذي كان سيجعل تجربتك أفضل، فراسلنا برسالة خاصة.',
    'آسفين جدًا يا {name} على التجربة دي. ده مش المستوى اللي بنقدمه، ياريت تتواصل معانا في رسالة خاصة عشان نحل المشكلة.' => 'نعتذر بشدة يا {name} عن هذه التجربة، فهي لا تمثل المستوى الذي نقدمه. نرجو التواصل معنا برسالة خاصة لنحل المشكلة.',
    'مفيش أرقام متاحة دلوقتي في المنطقة دي، بس ينفع تطلبه مسبقًا. علّم على "اطلبه مسبقًا" وابعت تاني.' => 'لا توجد أرقام متاحة حاليًا في هذه المنطقة، ويمكنك طلب رقم مسبقًا. حدّد "اطلبه مسبقًا" وأرسل مرة أخرى.',
    'فيه بيانات للدولة دي لسه تحت المراجعة. لو بعت تاني هيتعمل طلب جديد.' => 'توجد بيانات لهذه الدولة ما زالت قيد المراجعة. إذا أرسلت مرة أخرى فسيُنشأ طلب جديد.',
    'صحح البيانات اللي المراجعة رفضتها' => 'صحّح البيانات التي رفضتها المراجعة',
    'الدولة دي بتطلب تعرف مين صاحب الرقم قبل ما يتفعل. البيانات بتروح لمزود الأرقام مباشرة.' => 'تشترط هذه الدولة معرفة صاحب الرقم قبل تفعيله. تُرسل البيانات إلى مزود الأرقام مباشرة.',
    'استخدم بيانات اتقبلت قبل كده' => 'استخدم بيانات قُبلت سابقًا',
    'لو اخترت واحدة منهم مش محتاج تملا الفورم تاني.' => 'إذا اخترت إحداها فلن تحتاج إلى تعبئة النموذج مرة أخرى.',
    'PDF أو صورة · لحد 10 ميجا · البطاقة: الوشين في ملف واحد' => 'PDF أو صورة · حتى 10 ميجابايت · البطاقة: الوجهان في ملف واحد',
    'الأرقام اللي الشركة بتستخدمها في المكالمات والـ SMS وواتساب.' => 'الأرقام التي تستخدمها الشركة في المكالمات والرسائل النصية وواتساب.',
    'الدولة دي محتاجة بيانات هوية (KYC) قبل ما الرقم يشتغل.' => 'تتطلب هذه الدولة بيانات هوية (KYC) قبل تفعيل الرقم.',
    'الرقم التجريبي لواتساب: %s (للتجربة بس، مش رقمك).' => 'رقم واتساب التجريبي: %s (للتجربة فقط، وليس رقمك).',
    'اتحفظ القالب' => 'تم حفظ القالب',
    'تنبيه: الرقم ده لغى الاشتراك (STOP). زيرنيو هيرفض الرسالة من أرقام الشركة، ابعتها من رقمك لو عاوز توصله.' => 'تنبيه: ألغى هذا الرقم اشتراكه (STOP). سيرفض Zernio الرسالة من أرقام الشركة، فأرسلها من رقمك إن أردت أن تصله.',
    'دوس هنا مرة واحدة عشان الموبايل يبعت أي SMS جاية لرقمك للمنصة، ويبلغها بحالة الرسايل اللي بتتبعت.' => 'اضغط هنا مرة واحدة ليُرسل الهاتف أي رسالة نصية تصل إلى رقمك إلى المنصة، ويبلغها بحالة الرسائل المرسلة.',
