    'أهلاً! السعر ... وللطلب ابعتلنا هنا' => 'أهلًا! السعر ... وللطلب راسلنا هنا',
    'أهلاً {{contact.name}}! إزاي نقدر نساعدك؟' => 'أهلًا {{contact.name}}! كيف يمكننا مساعدتك؟',
    'أعد المحاولة للمنصات اللي فشلت' => 'أعد المحاولة للمنصات التي فشل النشر عليها',
    '+ اعمل مكالمة' => '+ أجرِ مكالمة',
    'مفيش حاجة اتحفظت لسه. راجع الاقتراح، وشيل العلامة من أي عنصر مش عايزه، وبعدين اعتمد.' => 'لم يُحفظ شيء بعد. راجع الاقتراح، وأزل العلامة عن أي عنصر لا تريده، ثم اعتمد.',
    'لسه مفيش. اللي هتكتبه هيتحفظ هنا على الجهاز ده.' => 'لا يوجد شيء بعد. ما تكتبه سيُحفظ على هذا الجهاز.',
    'لو قفلتها، محدش يقدر يسجل غير اللي معاه لينك دعوة.' => 'إذا أغلقتها، فلن يتمكن من التسجيل إلا من لديه رابط دعوة.',
    'لازم رقم أو إيميل. لو العميل موجود هيتدمج معاه بدل ما يتكرر.' => 'يلزم رقم أو بريد إلكتروني. إذا كان العميل موجودًا فسيُدمج معه بدلًا من تكراره.',
    'هيتحدّث كل الأقسام المليانة بالذكاء الاصطناعي. تقدر تتراجع في كل قسم لوحده. تكمل؟' => 'ستُحدَّث جميع الأقسام الممتلئة بالذكاء الاصطناعي، ويمكنك التراجع في كل قسم على حدة. هل تريد المتابعة؟',
    'دوس على أي مربع عشان تضيف أو تشيل ميعاد. اسحب على كذا مربع مرة واحدة.' => 'اضغط على أي مربع لإضافة موعد أو إزالته، أو اسحب على عدة مربعات دفعة واحدة.',
    'دي الحاجات اللي اتعلّم عليها بس. الطلب نفسه مش هيتحسب تاني.' => 'هذه العناصر المحددة فقط. لن يُحتسب الطلب نفسه مرة أخرى.',
    'بيتطبق على أي حد لسه ما اختارش لغة أو وضع بنفسه.' => 'يُطبَّق على كل من لم يختر لغة أو وضعًا بنفسه بعد.',
    'ده النص الكامل اللي بيستخدمه الذكاء الاصطناعي. امسح أي سطور ملهاش معنى واحفظ.' => 'هذا هو النص الكامل الذي يستخدمه الذكاء الاصطناعي. احذف أي أسطر لا معنى لها ثم احفظ.',
    'حذف المحادثة دي وكل رسايلها من Zernio؟ مش هينفع ترجعها.' => 'حذف هذه المحادثة وجميع رسائلها من Zernio؟ لا يمكن التراجع عن ذلك.',
    'تحذير: المنشور هيتمسح نهائياً من المنصة دي ومش هينفع يرجع. متأكد؟' => 'تحذير: سيُحذف المنشور نهائيًا من هذه المنصة ولا يمكن استرجاعه. هل أنت متأكد؟',
    'تمت إعادة المحاولة. راجع الحالة بعد شوية.' => 'تمت إعادة المحاولة. راجع الحالة بعد قليل.',
    'بيشتغل على المجدول والمسودات بس، والنسخ الخاصة بكل منصة كمان. الحروف لازم تبقى زي ما هي بالظبط.' => 'يعمل على المنشورات المجدولة والمسودات فقط، وكذلك النسخ الخاصة بكل منصة. يجب أن تتطابق الحروف تمامًا.',
    'حذف القالب ده نهائياً من واتساب؟ مش هينفع ترجعه، ولازم تستنى قبل ما تستخدم نفس الاسم تاني.' => 'حذف هذا القالب نهائيًا من واتساب؟ لا يمكن التراجع، وعليك الانتظار قبل استخدام الاسم نفسه مجددًا.',
    'حذف الجمهور ده من المنصة نهائياً؟ أي إعلان بيستخدمه ممكن يتأثر.' => 'حذف هذا الجمهور من المنصة نهائيًا؟ قد يتأثر أي إعلان يستخدمه.',
    'المسودة اتعملت واتضاف %s مستلم (اتساب %s). راجعها قبل الإرسال.' => 'أُنشئت المسودة وأُضيف %s مستلمًا (تم تخطي %s). راجعها قبل الإرسال.',
    'شيل جهة الاتصال دي من السلسلة؟' => 'إزالة جهة الاتصال هذه من السلسلة؟',
    'اختار قالب للخطوة الأولى عشان تشوف المعاينة.' => 'اختر قالبًا للخطوة الأولى لعرض المعاينة.',
    'المتوقع لحد النهارده: %s · محتاج %s في اليوم عشان توصل للهدف.' => 'المتوقع حتى اليوم: %s · تحتاج إلى %s يوميًا لبلوغ الهدف.',
    'بنفس السرعة دي هتقفل الشهر على %s (%s%% من الهدف).' => 'بهذه الوتيرة ستُنهي الشهر عند %s (%s%% من الهدف).',
    'اللي اتعمل %s' => 'المُنجز %s',
    'اتنشر:' => 'نُشر:',
    'نص خاص بالمنصة دي:' => 'نص خاص بهذه المنصة:',
    'الطابور هو مواعيد ثابتة في الأسبوع (مثلاً الاتنين 10 الصبح)، ولما تختار "ضيف للطابور" وأنت بتكتب منشور، بيتحط تلقائي في أقرب ميعاد فاضي.' => 'الطابور مواعيد أسبوعية ثابتة (مثلًا الاثنين 10 صباحًا)، وعند اختيار "أضف إلى الطابور" أثناء كتابة منشور يوضع تلقائيًا في أقرب موعد متاح.',
    'ميعاد بالدقيقة:' => 'موعد بالدقيقة:',
    'أعد ترتيب المنشورات اللي في الطابور على المواعيد الجديدة' => 'أعد توزيع منشورات الطابور على المواعيد الجديدة',
    'لو الرسالة دي وصلتك، يبقى التقارير والتنبيهات هتوصل كمان.' => 'إذا وصلتك هذه الرسالة، فستصلك التقارير والتنبيهات أيضًا.',
    'لو الرقم عليه "التحقق بخطوتين" في WhatsApp Manager، اكتب نفس الـ PIN بتاعه.' => 'إذا كان «التحقق بخطوتين» مفعّلًا على الرقم في WhatsApp Manager، فأدخل رمز PIN نفسه.',
    'لو مفيش PIN، اختار أي 6 أرقام وهيبقوا هما الـ PIN بتاع الرقم. احفظهم في مكان أمان.' => 'إذا لم يكن هناك رمز PIN، فاختر أي 6 أرقام لتصبح رمز PIN للرقم، واحفظها في مكان آمن.',
    'لو ظهرلك خطأ 133010 "Account not registered" وانت بتبعت، سجّل الرقم من هنا.' => 'إذا ظهر لك الخطأ 133010 «Account not registered» أثناء الإرسال، فسجّل الرقم من هنا.',
    'بيشيلها من البرنامج لكل الفريق. حساباتها ومنشوراتها في خدمة النشر مش بتتمسح.' => 'يزيلها من المنصة لكل الفريق، ولا تُحذف حساباتها ومنشوراتها في خدمة النشر.',
    'عشان الردود ماتبانش آلية، وفيسبوك مايعتبرهاش سبام. بيستهلك طلب لكل تعليق.' => 'حتى لا تبدو الردود آلية ولا يعدّها فيسبوك رسائل مزعجة. يستهلك طلبًا واحدًا لكل تعليق.',
    'عشان التقارير تتبعت والتنبيهات تتحدث لوحدها، ضيف الأمر ده في Cron Jobs في لوحة الاستضافة يشتغل كل ساعة:' => 'لكي تُرسل التقارير وتُحدَّث التنبيهات تلقائيًا، أضف هذا الأمر إلى Cron Jobs في لوحة الاستضافة ليعمل كل ساعة:',
    'عشان تبعت لأرقام أمريكية لازم الشركة والحملة يتسجلوا الأول. التسجيل بيتعمل من لوحة التكامل لأنه محتاج ورق ومراجعة.' => 'للإرسال إلى أرقام أمريكية يجب تسجيل الشركة والحملة أولًا. يتم التسجيل من لوحة التكامل لأنه يتطلب مستندات ومراجعة.',
    'كل مربع يوم وساعة. كل ما اللون أغمق، كل ما الرسايل اللي بتوصل أكتر. بتوقيت الشركة (%s).' => 'كل مربع يمثل يومًا وساعة، وكلما كان اللون أغمق زاد عدد الرسائل الواردة. بتوقيت الشركة (%s).',
    'منين بييجي العملاء، وأنهي مصدر بيتحول لعملاء فعلًا. ركّز مجهودك على اللي نسبته أعلى.' => 'من أين يأتي العملاء المحتملون، وأي مصدر يتحول إلى عملاء فعليين. ركّز جهدك على المصادر الأعلى نسبة.',
    'كل رسالة قالب على واتساب بتتحاسب عليها من Meta حسب نوع القالب وبلد المستلم. بعد الإرسال مفيش رجوع: الرسايل مش هينفع تتسحب.' => 'تحتسب Meta تكلفة كل رسالة قالب على واتساب حسب نوع القالب وبلد المستلم. لا تراجع بعد الإرسال، إذ لا يمكن سحب الرسائل.',
    'ماتستخدموش في رسايل جماعية كتير: شركات الاتصالات بتوقف الخطوط اللي بتبعت سبام، والمنصة حاطة حد أقصى 20 رسالة في الدقيقة.' => 'لا تستخدمه في الرسائل الجماعية الكثيرة، فشركات الاتصالات توقف الخطوط التي ترسل رسائل مزعجة، والمنصة تضع حدًا أقصى قدره 20 رسالة في الدقيقة.',
    '<p class="text-center text-sm text-slate-600">اللينك ده منتهي أو اتلغى. اطلب لينك جديد من صاحب الشركة.</p>' => '<p class="text-center text-sm text-slate-600">انتهت صلاحية هذا الرابط أو أُلغي. اطلب رابطًا جديدًا من مالك الشركة.</p>',
    '<p class="text-center text-sm text-slate-600">الدعوة دي متبعتة لإيميل تاني. انت داخل بـ <span dir="ltr">' => '<p class="text-center text-sm text-slate-600">هذه الدعوة مرسلة إلى بريد آخر. أنت مسجّل الدخول بـ <span dir="ltr">',
    'محاولات كتير. استنى 15 دقيقة.' => 'محاولات كثيرة. انتظر 15 دقيقة.',
    'فيه حساب بالإيميل ده. سجل دخول بدل ما تعمل حساب جديد.' => 'يوجد حساب بهذا البريد. سجّل الدخول بدلًا من إنشاء حساب جديد.',
    'مالك الشركة بس يقدر يغيّر دور مالك تاني أو يشيله.' => 'لا يستطيع تغيير دور مالك آخر أو إزالته إلا مالك الشركة.',
    'المالك ليه كل الصلاحيات دايماً.' => 'للمالك جميع الصلاحيات دائمًا.',
    'لو عنده حساب: الدعوة بتظهرله جوه البرنامج. لو معندوش: هيطلعلك لينك تبعتهوله.' => 'إن كان لديه حساب فستظهر له الدعوة داخل المنصة، وإلا فسيظهر لك رابط ترسله إليه.',
    'اتعملت شركة "%s" وانت صاحبها. اربطها من صفحة التكاملات عشان تبدأ.' => 'أُنشئت الشركة "%s" وأنت مالكها. اربطها من صفحة التكاملات لتبدأ.',
    'انت صاحب الشركة الوحيد. اعمل حد تاني صاحب شركة الأول، أو احذف الشركة.' => 'أنت المالك الوحيد للشركة. عيّن مالكًا آخر أولًا، أو احذف الشركة.',
    'اعمل شركة جديدة من الفورم، أو اطلب من صاحب شركة يبعتلك لينك دعوة.' => 'أنشئ شركة جديدة من النموذج، أو اطلب من مالك شركة أن يرسل إليك رابط دعوة.',
    'اختار دولتها من الإعدادات وادعي فريقها' => 'اختر دولتها من الإعدادات وادعُ فريقها',
    'كل شركة ليها مفاتيحها وفريقها لوحدها.' => 'لكل شركة مفاتيحها وفريقها المستقل.',
    'المنصات (زي لينكدإن وX) ممكن ترفض أو تقلل وصول المنشور المكرر. خلّي كل نسخة بصياغة مختلفة.' => 'قد ترفض المنصات (مثل لينكدإن وX) المنشور المكرر أو تقلّل وصوله. اجعل لكل نسخة صياغة مختلفة.',
    '%s هاشتاج كتير على فيسبوك/لينكدإن (الأحسن 3-5)' => '%s وسمًا عدد كبير على فيسبوك/لينكدإن (الأفضل 3-5)',
