    'اتقدم' => 'قُدِّم',
    'أي حد يرد بكلمة STOP بيتشال من الإرسال تلقائياً، ولو حاولت تبعتله الرسالة هترفض. بيرجع بس لو رد بكلمة START.' => 'من يرد بكلمة STOP يُستبعد من الإرسال تلقائيًا، وتُرفض أي رسالة تُرسل إليه، ولا يعود إلا إذا رد بكلمة START.',
    'الرقم %s اتشرى.' => 'تم شراء الرقم %s.',
    'لازم تعلّم على مربع التأكيد قبل إلغاء الرقم.' => 'يجب تحديد مربع التأكيد قبل إلغاء الرقم.',
