    'املا بيانات الهوية للرقم ده ←' => 'املأ بيانات الهوية لهذا الرقم ←',
    'الأرقام في الدولة دي بتتطلب مع بيانات الهوية في خطوة واحدة.' => 'تُطلب الأرقام في هذه الدولة مع بيانات الهوية في خطوة واحدة.',
    'اتطلب' => 'طُلب',
    'فاهم إن الرقم هيروح نهائياً، وأي واتساب أو مكالمات أو رسايل عليه هتقف.' => 'أدرك أن الرقم سيُحذف نهائيًا، وسيتوقف أي واتساب أو مكالمات أو رسائل مرتبطة به.',
    'اكتب الرقم بالصيغة الدولية، مثلاً %s.' => 'اكتب الرقم بالصيغة الدولية، مثلًا %s.',
    'أي خط، أي شبكة (فودافون، أورنج، اتصالات، WE…)، عن طريق موبايل أندرويد قديم عليه الخط. الرسايل بتتحسب من باقة الخط نفسه.' => 'أي خط على أي شبكة (فودافون، أورنج، اتصالات، WE…)، عبر هاتف أندرويد قديم مُركَّب فيه الخط. تُحتسب الرسائل من باقة الخط نفسه.',
    'من صفحة التكاملات اختار "رقمي من موبايل أندرويد" وحط اسم المستخدم وكلمة السر. المنصة هتجرب الاتصال قبل الحفظ.' => 'من صفحة التكاملات اختر "رقمي من هاتف أندرويد" وأدخل اسم المستخدم وكلمة المرور. ستختبر المنصة الاتصال قبل الحفظ.',
