    'حدد مواعيد اليوم الخاص أو علّم إنه مقفول.' => 'حدد مواعيد اليوم الخاص أو اختر أنه مغلق.',
    'اكتب صنف واحد على الأقل بالشكل: القسم | الصنف | السعر' => 'أدخل صنفًا واحدًا على الأقل بالصيغة: القسم | الصنف | السعر',
    'المواعيد الخاصة الحالية للفروع المختارة هتتمسح وتتبدل باللي هنا بالظبط.' => 'ستُحذف المواعيد الخاصة الحالية للفروع المختارة وتُستبدل بما هنا تمامًا.',
    'اختار طريقة التحقق المتاحة (فيديو، تليفون، إيميل، أو بريد) وكمل الخطوات.' => 'اختر طريقة التحقق المتاحة (فيديو أو هاتف أو بريد إلكتروني أو بريد عادي) وأكمل الخطوات.',
    'بعد ما التحقق يكتمل، الحالة هنا هتتحدث لوحدها.' => 'بعد اكتمال التحقق ستُحدَّث الحالة هنا تلقائيًا.',
    '%s خدمة من قايمة جوجل الجاهزة هتفضل زي ما هي.' => 'ستبقى %s خدمة من قائمة جوجل الجاهزة كما هي.',
    'المفعّل بس' => 'المفعّل فقط',
    'اترفعت على %s فروع ✓' => 'رُفعت على %s فروع ✓',
    'التصحيحات اتبعتت للمراجعة. الرقم بيتفعل عادة خلال 1–3 أيام عمل بعد القبول.' => 'أُرسلت التصحيحات للمراجعة. يُفعَّل الرقم عادةً خلال 1–3 أيام عمل بعد القبول.',
    'الرقم اتطلب مسبقًا وهيتوفر خلال أسابيع.' => 'طُلب الرقم مسبقًا وسيتوفر خلال أسابيع.',
    'للشركات بس' => 'للشركات فقط',
    'مش أقدم من %s شهور' => 'لا يزيد عمره على %s أشهر',
    'اكتب العنوان بالإنجليزي زي ما هو مكتوب في المستندات.' => 'اكتب العنوان بالإنجليزية كما هو مدوَّن في المستندات.',
    'بعد ما الطلب يتبعت، هيظهر لك في صفحة الأرقام لينك تحقق بالوش والبطاقة من الموبايل (دقيقتين).' => 'بعد إرسال الطلب سيظهر لك في صفحة الأرقام رابط للتحقق بالوجه والهوية من الهاتف (دقيقتان).',
    'يرد بالرسالة دي' => 'يرد بهذه الرسالة',
    'العنوان يقبل متغير واحد بس.' => 'يقبل العنوان متغيرًا واحدًا فقط.',
    'اسم القالب لازم يبدأ بحرف إنجليزي صغير وفيه حروف صغيرة وأرقام و _ بس.' => 'يجب أن يبدأ اسم القالب بحرف إنجليزي صغير، وأن يحتوي على حروف صغيرة وأرقام و _ فقط.',
