    'الرقم مش متسجل للإرسال (الحالة: %s). الرسايل مش هتتبعت لحد ما تسجله.' => 'الرقم غير مسجّل للإرسال (الحالة: %s). لن تُرسل الرسائل حتى تسجّله.',
