    'البيانات صحيحة ومطابقة للمستندات، وفاهم إن الرقم بيتحسب بعد ما يتفعل.' => 'البيانات صحيحة ومطابقة للمستندات، وأعلم أن الرقم يُحتسب بعد تفعيله.',
    'فاهم إن الرقم هيتحسب عليه %s كل شهر بعد ما يتفعل، والبيانات صحيحة ومطابقة للمستندات.' => 'أعلم أن الرقم سيُحتسب بـ %s شهريًا بعد تفعيله، وأن البيانات صحيحة ومطابقة للمستندات.',
    'فورم "اتصل بيا" (رقم بس، زرار واحد)' => 'نموذج "اتصل بي" (رقم فقط، زر واحد)',
    'بيبص على العملاء اللي كسبتهم ويملا الفلاتر بأكتر حاجات متكررة فيهم' => 'يحلّل العملاء الذين كسبتهم ويملأ عوامل التصفية بأكثر السمات تكرارًا بينهم',
    'العائد محسوب من قيمة الصفقات اللي سجلتها هنا للعملاء اللي "بقوا عملاء"' => 'يُحسب العائد من قيمة الصفقات المسجلة هنا للعملاء الذين أصبحوا عملاء',
    'موافق على تغيير الميزانية اليومية للحملات المحددة. ده بيأثر على الصرف الفعلي.' => 'أوافق على تغيير الميزانية اليومية للحملات المحددة، وهذا يؤثر على الإنفاق الفعلي.',
    'لو كملت خطوات الربط، الحساب هيظهر في القائمة تحت.' => 'إذا أكملت خطوات الربط، فسيظهر الحساب في القائمة أدناه.',
    'العنوان هيظهر هنا' => 'سيظهر العنوان هنا',
    'ميتا بتعرض البلد والمدينة بس لصفحات فيسبوك، وبيظهروا لما الصفحة يبقى عندها متابعين كفاية.' => 'تعرض ميتا البلد والمدينة لصفحات فيسبوك فقط، ويظهران عندما يبلغ عدد متابعي الصفحة حدًّا كافيًا.',
    'اطبع الـ QR وحطه في المحل أو المعرض أو على الكروت. اللي يمسحه بيوصل للفورم ويتسجل Lead على طول.' => 'اطبع رمز QR وضعه في المتجر أو المعرض أو على البطاقات. من يمسحه يصل إلى النموذج ويُسجَّل عميلًا محتملًا فورًا.',
    'صفحة لكل حملة من غير موقع: عنوان، وصف، صورة، زرار واتساب، وفورم. حط لينكها في الإعلان أو البايو، وكل اللي يسجّل بيتعلّم باسم الحملة.' => 'صفحة لكل حملة دون الحاجة إلى موقع: عنوان ووصف وصورة وزر واتساب ونموذج. ضع رابطها في الإعلان أو النبذة، وسيُوسم كل من يسجّل باسم الحملة.',
    'ابعت لكل عميل لينك خاص بيه. أي حد يسجّل منه بيتكتب إنه جه من العميل ده، وبياخد نقط أعلى، والعميل الأصلي بيتسجل عنده إنه جاب حد.' => 'أرسل لكل عميل رابطًا خاصًا به. يُنسب كل من يسجّل عبره إلى هذا العميل ويحصل على نقاط أعلى، ويُسجَّل للعميل الأصلي أنه أحال شخصًا.',
    'ليه بنخسر العملاء' => 'لماذا نخسر العملاء',
    'متأكد إنك عاوز تحذف الطابور ده؟ المنشورات اللي متحطة فيه ممكن تتأثر.' => 'هل تريد حذف هذا الطابور؟ قد تتأثر المنشورات المدرجة فيه.',
    'اكتب رسالة كأنك عميل، وشوف الذكاء الاصطناعي هيرد إزاي أو هيحوّل لموظف. ده نفس اللي هيحصل في الرد التلقائي.' => 'اكتب رسالة كأنك عميل، وشاهد كيف سيرد الذكاء الاصطناعي أو يحوّل المحادثة إلى موظف. هذا ما سيحدث تمامًا في الرد التلقائي.',
    'ليه تختارنا' => 'لماذا تختارنا',
    'التعديل هيظهر على المنصة فوراً. تكمل؟' => 'سيظهر التعديل على المنصة فورًا. هل تريد المتابعة؟',
    'محادثات أوتوماتيك: لما حد يبعت رسالة أو يكتب تعليق فيه كلمة معينة، البرنامج يرد عليه بالخطوات اللي حددتها.' => 'محادثات تلقائية: عندما يرسل أحدهم رسالة أو يكتب تعليقًا يحتوي على كلمة معينة، يرد عليه النظام بالخطوات التي حددتها.',
    'مثلاً: نادي العميل باسمه، ونقول "حضرتك"، ونختم بـ "في خدمتك دايمًا"' => 'مثلًا: نادِ العميل باسمه، وخاطبه بـ"حضرتك"، واختم بـ"في خدمتك دائمًا"',
    'مثلاً: تصوير منتجات بإضاءة طبيعية، خلفيات فاتحة بسيطة، أشخاص حقيقيين مش رسومات' => 'مثلًا: تصوير منتجات بإضاءة طبيعية، وخلفيات فاتحة بسيطة، وأشخاص حقيقيون لا رسومات',
    'مثلاً صلاة الجمعة أو بعد نص الليل. صفحة الإنشاء بتنبهك لو اخترت وقت منهم، و"املا الفراغات" بيتجنبها.' => 'مثلًا صلاة الجمعة أو بعد منتصف الليل. تنبّهك صفحة الإنشاء إذا اخترت أحد هذه الأوقات، ويتجنبها خيار "املأ الفراغات".',
    'لو الخانة فيها الكلمة دي، العميل ياخد التاج ده لوحده أول ما يتضاف. مثلًا: الشركة فيها "مطعم" ← مطاعم، أو الرقم يبدأ بـ 966 ← السعودية.' => 'إذا احتوى الحقل على هذه الكلمة، يحصل العميل على هذا الوسم تلقائيًا فور إضافته. مثلًا: الشركة تحتوي على "مطعم" ← مطاعم، أو الرقم يبدأ بـ 966 ← السعودية.',
    'لـ %1، اللي %2، إحنا %3. على عكس %6، %4. والدليل: %5.' => 'لـ%1 الذين %2، نحن %3. على عكس %6، %4. والدليل: %5.',
    'كل ساعة بنلف على آخر المنشورات ونخفي التعليقات اللي فيها شتايم أو لينكات سبام. التعليق بيتخفي مش بيتمسح، وتقدر ترجّعه من المنصة.' => 'نراجع أحدث المنشورات كل ساعة ونخفي التعليقات التي تحتوي على شتائم أو روابط مزعجة. يُخفى التعليق ولا يُحذف، ويمكنك استعادته من المنصة.',
    'غيّر الأسماء والألوان، وضيف لحد 4 مراحل زيادة (بتتحط قبل "بقى عميل"). "جديد" و"بقى عميل" و"مش مناسب" أساسيين في التقارير فمابيتمسحوش.' => 'غيّر الأسماء والألوان، وأضف حتى 4 مراحل إضافية (توضع قبل "أصبح عميلًا"). المراحل "جديد" و"أصبح عميلًا" و"غير مناسب" أساسية في التقارير فلا يمكن حذفها.',
    'شكل موحد لكل إيميلات العملاء (من التفاصيل، والخطط، والإيميل الجماعي): لوجو ولون وتوقيع. كل إيميل فيه رابط إلغاء اشتراك، واللي يلغي مابيوصلوش حاجة تاني.' => 'مظهر موحد لكل رسائل البريد إلى العملاء (من التفاصيل والخطط والبريد الجماعي): شعار ولون وتوقيع. تحتوي كل رسالة على رابط لإلغاء الاشتراك، ومن يلغِ اشتراكه لا تصله رسائل أخرى.',
    'سحب عشوائي عادل من الناس اللي علّقوا هنا (كل شخص فرصة واحدة مهما علّق). تقدر تشترط كلمة أو منشن.' => 'سحب عشوائي عادل بين من علّقوا هنا (فرصة واحدة لكل شخص مهما علّق). يمكنك اشتراط كلمة أو إشارة.',
    'ردود جاهزة للمنشور ده بس (السعر، العنوان، طريقة الطلب). دوس على الرد يتحط في خانة الكتابة.' => 'ردود جاهزة لهذا المنشور فقط (السعر، العنوان، طريقة الطلب). اضغط على الرد لإدراجه في خانة الكتابة.',
    'بيسأل عن الميزانية وإمتى محتاج. اللي عاوز يبدأ دلوقتي بياخد نقط أعلى ويطلع فوق في العملاء.' => 'يسأل عن الميزانية وموعد الحاجة. من يريد البدء الآن يحصل على نقاط أعلى ويظهر في أعلى قائمة العملاء.',
    'بيتضاف تلقائيًا لكل صورة بتتولد من Higgsfield، لو مفيش ستايل مكتوب في إعدادات Higgsfield.' => 'يُضاف تلقائيًا إلى كل صورة تُولَّد عبر Higgsfield إذا لم يُحدَّد نمط في إعدادات Higgsfield.',
    'النظام هيتصل بالعميل من رقم الشركة، ولما يرد هيوصله بالرقم اللي تكتبه في "وصّلها على" (موبايلك مثلاً). المكالمة بتتحسب بالدقيقة.' => 'سيتصل النظام بالعميل من رقم الشركة، وعندما يرد سيوصله بالرقم الذي تكتبه في "حوّلها إلى" (جوالك مثلًا). تُحتسب المكالمة بالدقيقة.',
    'اللي يدخل من لينك إحالة يشوف اسم اللي رشّحه والهدية' => 'من يدخل عبر رابط إحالة يرى اسم من رشّحه والهدية',
    'الكلام اللي اتقرا — اضغط على سطر وبعدين على الخانة اللي يروح لها' => 'النص المقروء: اضغط على سطر ثم على الحقل الذي يُنقل إليه',
    'الـ Workflow بيتعمل كمسودة، ومش هيشتغل غير لما تدوس تشغيل.' => 'يُنشأ الـWorkflow كمسودة، ولن يعمل إلا بعد الضغط على تشغيل.',
    'الـ Leads دي متربطة بالـ Leads الموحدة، والمرحلة بتتحدّث في المكانين.' => 'هذه الـLeads مرتبطة بالـLeads الموحدة، وتُحدَّث المرحلة في المكانين.',
    'العميل اللي يكتب الكود في كومنت أو رسالة واتضاف Lead، بيتسجل عليه الكوبون.' => 'العميل الذي يكتب الرمز في تعليق أو رسالة ويُضاف كـLead يُسجَّل عليه الكوبون.',
