    'Zernio رد إن التعديل تم، بس الميعاد مااتغيرش (لسه %s). افتح "تشخيص تغيير المواعيد" تحت الصفحة وابعتلي اللي فيه.' => 'أفاد Zernio بأن التعديل تم، لكن الموعد لم يتغير (ما زال %s). افتح "تشخيص تغيير المواعيد" أسفل الصفحة وأرسل لنا محتواه.',
