    '%s%% من الرسايل اللي اتبعتت فشلت (%s رسالة). راجع ربط الحسابات وقواعد الإرسال (زي نافذة الـ 24 ساعة في واتساب).' => 'فشل إرسال %s%% من الرسائل (%s رسالة). راجع ربط الحسابات وقواعد الإرسال (مثل نافذة الـ 24 ساعة في واتساب).',
    'الحسابات دي مالهاش إحصائيات مباشرة من المنصة، وأرقام منشوراتها موجودة في تبويب النظرة العامة والمنشورات:' => 'لا تتوفر لهذه الحسابات إحصائيات مباشرة من المنصة، وأرقام منشوراتها موجودة في تبويبي النظرة العامة والمنشورات:',
    'أرباح أعلى منشورات الصفحة في الفترة (من بداية المنشور). بتظهر بس لو الصفحة مفعّل فيها تحقيق الدخل.' => 'أرباح أعلى منشورات الصفحة خلال الفترة (منذ نشر المنشور). تظهر فقط إذا كان تحقيق الدخل مفعّلًا في الصفحة.',
    'لما حد يكتب كلمة معينة في تعليق، يوصله رد تلقائي في الخاص و/أو رد عام تحت تعليقه. الرسائل الخاصة متاحة على إنستجرام وفيسبوك بس.' => 'عندما يكتب أحد كلمة معيّنة في تعليق، يصله رد تلقائي في الخاص و/أو رد عام تحت تعليقه. الرسائل الخاصة متاحة على إنستجرام وفيسبوك فقط.',
    'لما حد يكتب تعليق فيه واحدة من الكلمات دي، البرنامج بيبعتله الرسالة الخاصة أوتوماتيك، وممكن كمان يرد عليه رد عام تحت التعليق.' => 'عندما يكتب أحد تعليقًا يحتوي على إحدى هذه الكلمات، يرسل له النظام الرسالة الخاصة تلقائيًا، ويمكنه أيضًا الرد عليه ردًا عامًا تحت التعليق.',
    'اربط الحساب من "الحسابات المربوطة"، أو شيل %s من عمود platforms.' => 'اربط الحساب من "الحسابات المربوطة"، أو احذف %s من عمود platforms.',
    'الرقم ده عليه إعدادات متقدمة (قايمة اختيارات أو تحويل لنظام آلي). عدلها من لوحة التكامل عشان ماتتمسحش.' => 'على هذا الرقم إعدادات متقدمة (قائمة خيارات أو تحويل إلى نظام آلي). عدّلها من لوحة التكامل حتى لا تُحذف.',
