    'ابعت رسالة خاصة لصاحب تعليق على فيسبوك أو إنستجرام. مسموح برسالة واحدة لكل تعليق خلال 7 أيام من كتابته.' => 'أرسل رسالة خاصة إلى صاحب تعليق على فيسبوك أو إنستجرام. يُسمح برسالة واحدة لكل تعليق خلال 7 أيام من نشره.',
    'Gmail / Google Workspace: السيرفر smtp.gmail.com، البورت 587 TLS، وكلمة السر لازم تكون App Password مش كلمة سر الحساب.' => 'Gmail / Google Workspace: الخادم smtp.gmail.com، المنفذ 587 TLS، ويجب أن تكون كلمة المرور App Password لا كلمة مرور الحساب.',
    'اختار الأقسام. الذكاء الاصطناعي هيستخدم كل الملفات والأقسام التانية وبيانات حسابك، ويكمّل الناقص كخبير. كل قسم بيطلع كاقتراح تراجعه.' => 'اختر الأقسام. سيستخدم الذكاء الاصطناعي جميع الملفات والأقسام الأخرى وبيانات حسابك، ويُكمل الناقص كخبير. يظهر كل قسم اقتراحًا تراجعه.',
    'افصل المبيعات عن التوظيف أو الشراكات. كل Pipeline ليه قايمته ولوحته في صفحة العملاء، والعميل تقدر تنقله من تفاصيله.' => 'افصل المبيعات عن التوظيف أو الشراكات. لكل Pipeline قائمته ولوحته في صفحة العملاء، ويمكنك نقل العميل من صفحة تفاصيله.',
    'الأسماء والشروح جاية من مزود الأرقام بالإنجليزي زي ما هي عشان مايتغيرش معناها.' => 'الأسماء والشروح واردة من مزوّد الأرقام بالإنجليزية كما هي حتى لا يتغير معناها.',
    'الجودة بتقل لما الناس تبلّك أو تبلغ عن رسايلك. ابعت للي طالبين بس، وخلّي فيه طريقة للإلغاء.' => 'تنخفض الجودة عندما يحظرك الناس أو يبلّغون عن رسائلك. أرسل لمن طلبوا ذلك فقط، ووفّر طريقة لإلغاء الاشتراك.',
    'الرقم ده مشترك بين كل المستخدمين عشان تجرّب الرسايل بس. مالوش بروفايل بيزنس ولا جودة ولا حد رسايل خاص بيك، فمفيش حاجة تتعدل أو تتعرض هنا.' => 'هذا الرقم مشترك بين جميع المستخدمين لتجربة الرسائل فقط. ليس له ملف تجاري ولا تقييم جودة ولا حد رسائل خاص بك، لذا لا يوجد ما يمكن تعديله أو عرضه هنا.',
    'مربعة، JPG أو PNG، يفضل 640×640. اختار من المكتبة أو حط رابط https.' => 'مربعة، بصيغة JPG أو PNG، ويُفضّل 640×640. اختر من المكتبة أو أدخل رابط https.',
    'الحفظ بيفعّل المكالمات العادية على الرقم لو مش مفعلة. المكالمات الواردة بتتحول على رقم التحويل، ولو مفيش حد رد بتروح للبريد الصوتي.' => 'يؤدي الحفظ إلى تفعيل المكالمات العادية على الرقم إن لم تكن مفعّلة. تُحوَّل المكالمات الواردة إلى رقم التحويل، وإن لم يُجب أحد تذهب إلى البريد الصوتي.',
    'كام يوم من أول ما العميل اتسجل لحد ما بقى عميل (للي اتقفلوا في الفترة دي).' => 'عدد الأيام من تسجيل العميل المحتمل حتى تحوّله إلى عميل (للصفقات المغلقة في هذه الفترة).',
    'شكرًا يا {name} على كلامك الجميل! سعداء إن التجربة عجبتك، ومستنيينك تاني قريب.' => 'شكرًا لك يا {name} على كلماتك الطيبة! يسعدنا أن التجربة نالت إعجابك، ونتطلع لزيارتك مرة أخرى قريبًا.',
