    '"تواصل" = مكالمات وواتساب وإيميلات واجتماعات اتسجلت. "سرعة أول رد" = من وقت ما العميل اتضاف لحد أول تواصل معاه. حد الكشف اليومي لكل موظف: %s.' => '"التواصل" = المكالمات ورسائل واتساب والرسائل الإلكترونية والاجتماعات المسجّلة. "سرعة أول رد" = المدة من إضافة العميل حتى أول تواصل معه. حد الكشف اليومي لكل موظف: %s.',
    'حسابات ثابتة من غير ذكاء اصطناعي: الحملة اللي صرفت ومجابتش عملاء أو عائدها سالب بتقل ميزانيتها %s%%، والفلوس دي بتروح للحملات اللي بتبيع بعائد عالي (على قد عائدها، ومن غير ما تزيد أكتر من %s%% في المرة). إجمالي الميزانية اليومية مابيزيدش. مفيش حاجة بتتنفذ غير لما توافق.' => 'حسابات ثابتة دون ذكاء اصطناعي: الحملة التي أنفقت ولم تجلب عملاء أو كان عائدها سالبًا تُخفَّض ميزانيتها %s%%، ويُنقل هذا المبلغ إلى الحملات ذات العائد المرتفع (بقدر عائدها، ودون زيادة تتجاوز %s%% في المرة الواحدة). لا يزيد إجمالي الميزانية اليومية، ولا يُنفَّذ شيء إلا بعد موافقتك.',
